import React, { memo, SFC } from 'react';
import { Text, View } from 'react-native';
import * as AnalyticsDefinitions from '../../lib/AnalyticsDefinitions';
import Skeleton from '../Skeleton';
import TouchableWrapper from '../TouchableWrapper';
import UserImage from '../UserImage';
import styles from './styles';

interface UserAtom {
  facebookProfilePhoto: string;
  shortName: string;
  firstName: string;
  lastName: string;
}

export interface Props extends UserAtom {
  shouldHideName?: boolean;
  isVertical?: boolean;
  onPress?: () => void | undefined;
  noTouching?: boolean;
  isSelected?: boolean;
  isLoading?: boolean;
  style?: any;
}

const UserAvatar: SFC<Props> = ({
  facebookProfilePhoto,
  firstName,
  lastName,
  shortName,
  shouldHideName = false,
  isVertical = true,
  onPress,
  noTouching,
  isSelected = false,
  isLoading = false,
  style = {}
}: Props) => {
  const _containerStyle = [
    styles.container,
    { flexDirection: isVertical ? 'column' : 'row' },
    style
  ];

  if (isLoading) {
    return (
      <View style={_containerStyle}>
        <UserImage isLoading />
        {shouldHideName ? null : (
          <Skeleton
            childStyle={
              isVertical ? styles.skeletonVertical : styles.skeletonHorizontal
            }
          />
        )}
      </View>
    );
  }

  return (
    <TouchableWrapper
      style={_containerStyle}
      onPress={onPress}
      noTouching={noTouching}
      eventName={AnalyticsDefinitions.category.ACTION}
      eventParams={{
        [AnalyticsDefinitions.parameters.LABEL]:
          AnalyticsDefinitions.label.USER_AVATAR,
        [AnalyticsDefinitions.parameters.TYPE]: AnalyticsDefinitions.type.PRESS,
        [AnalyticsDefinitions.parameters.STATUS]: isSelected
          ? AnalyticsDefinitions.status.ACTIVE
          : AnalyticsDefinitions.status.INACTIVE
      }}
    >
      <UserImage uri={facebookProfilePhoto} size='small' />
      {shouldHideName ? null : (
        <Text
          style={[
            isVertical ? styles.verticalName : styles.horizontalName,
            isSelected ? styles.selectedName : {}
          ]}
        >
          {isVertical ? `${shortName}` : `${firstName} ${lastName}`}
        </Text>
      )}
    </TouchableWrapper>
  );
};

export default memo(UserAvatar);
